  ["d20cd47c8400d731"] = { "Mmm, ti ha mandato Narm da me, vero?\n\nBe', di Narm ci si è sempre potuti fidare, quindi vuol dire che sei pront<o/a> a prendere parte alla prossima sapta: la sapta del fuoco.\n\nLo vedo già nei tuoi occhi, l'ardore, il desiderio. Hai assaggiato il potere e ora ne vuoi ancora. Pazienza, {name}. Ricorda ciò che ti ha insegnato la terra. Potere e distruzione arriveranno facilmente, ma devi comunque sapere quando trattenere la mano.", "." },
  ["d22da951ba64e345"] = { "<Stolto/Stolta> {class}! Non puoi nulla contro la mia potenza!", "." },
  ["d2456803cc3849c5"] = { "Il mio popolo non ti conosce. Il kodo è una cavalcatura possente, frutto dell'amore e delle cure del mio popolo; non lo si concede a degli estranei. Finché gli anziani di ⟦Thunder Bluff=Picco del Tuono⟧ non ti considereranno <amico/amica>, non posso venderti un kodo.", "." },
  ["d2512d20b6d23ca5"] = { "Il mio signore, lord Abernathy, ti manda questo.", "." },
  ["d252158535c128e0"] = { "Cerca Austil de Mon nella sala da pranzo principale della Taverna dell'Impiccato. La taverna si trova al margine sud-orientale di Brill.", "." },
  ["d254b7fd8960a8d6"] = { "** PIAZZATA. CONFERMA DEL BLOCCO SUL WAR RIDER. IN ATTESA. T-MENO 60 SECONDI. **", "." },
  ["d2574ec4af2b5fed"] = { "Non credo proprio. Rimblat ha già dimostrato che nuova vita può nascere dalla terra squarciata. Ora dobbiamo trovare un modo per riprodurre e, soprattutto, sostenere la crescita.\n\nMentre sono qui, offro anche i miei servigi agli avventurieri diretti a Naxxramas.", "." },
  ["d25956791d611e49"] = { "Non arriverai al limitare della foresta, Fordring.", "." },
  ["d26016cc2f49e885"] = { "*Unità Threshwackonator First Mate pronta a seguirti*", "." },
  ["d26cc3cdf9c73e08"] = { "<Tarsis è gravemente ferito.>", "." },
  ["d2709c9d6140f243"] = { "Lassù vive ⟦Charlga Razorflank=Charlga Fiancospino⟧. Maledetta vecchia megera.", "." },
  ["d27f3e1632e5165b"] = { "MORITE, MORTALI!", "." },
  ["d2834de4f88d416b"] = { "Riesci a vederli, mortale? No... immaginavo di no. Vedente ma cieco: è il tuo dono e la tua maledizione.", "." },
  ["d28f3a18fcff7724"] = { "Già, Clyde Kellen lo trovi sempre a pescare sulla riva del ⟦Brightwater Lake=Lago di Acqualucente⟧, appena a est di Brill. Solo, quando sei là fuori, fa' attenzione agli psicopatici con la maschera. L'anno scorso abbiamo dovuto chiudere il campo estivo dei ragazzi.", "." },
  ["d299426d276a1c64"] = { "Ti serve la ⟦Hall of Legends=Sala delle Leggende⟧. Si trova in alto sopra la ⟦Valley of Strength=Valle della Forza⟧, sul lato ovest. Se non sei un ufficiale non puoi entrare, ma puoi comunque parlare con il sergente Ba'sha, fuori.", "." },
  ["d2a0e6a69382621a"] = { "Quindi... i Terrigeni erano fatti di pietra?", "." },
  ["d2a58e9fb644ea16"] = { "Ehi, Knot, conosco la Sartoria. Pensi di potermi insegnare a fare il completo da ogre?", "." },
  ["d2af1bb5f3135845"] = { "Non posso insegnarti la Conciatura Tribale, {name}. Devi andare a Tanaris e trovare la casa di ⟦Narain Soothfancy=Narain Veravite⟧. Una volta lì, consulta il libro «Soothsaying for Dummies».", "." },
  ["d2b403e1d9b2559e"] = { "Per l'⟦Horde=Orda⟧!", "." },
  ["d2b49a6a4ba496d7"] = { "La morte dell'imperatore Thaurissan sconvolge visibilmente %s.", "." },
  ["d2b5b14d3838496d"] = { "Hic!", "." },
  ["d2b6229d4ecb9b6e"] = { "Se hai perso un pezzo della tua armatura degli Zandalari, forse posso aiutarti.", "." },
  ["d2b64803fc917dff"] = { "Cosa intendi con «puro»?", "." },
  ["d2bac67400c9c948"] = { "La battaglia è finita, e la gente del ⟦Darrowshire=Borgo di Darrow⟧ è salva.", "." },
  ["d2c21a316fc01110"] = { "Non sarà la fine della ⟦Scarlet Crusade=Crociata Scarlatta⟧! Non spezzerete la nostra linea!", "." },
  ["d2c46f523785a78d"] = { "%s evoca un messaggero...", "." },
  ["d2c6b1ac379c8c0b"] = { "La tua armatura fa paura. Fai paura anche tu?", "." },
  ["d2cc1927b7d21233"] = { "Lo spirito del Maldestriero pulsa di rabbia.", "." },
  ["d2d3fabd35a26bdb"] = { "Le ⟦Plaguelands=Terre Infette⟧ sono il posto ideale per colpire il Flagello!", "." },
  ["d2e29cada028a868"] = { "Le mie creazioni godono di una certa fama, {class}. Con i materiali giusti posso realizzare un'armatura nota come Vagasogni. I druidi, e persino alcuni sciamani, sono attratti da questa armatura per le sue proprietà magiche. Ti interessa?", "." },
  ["d2e5b31cb159d23c"] = { "Ho sentito che a ⟦Undercity=Sepulcra⟧ c'è un istruttore di Estrazione. Per arrivarci basta uscire dal paese verso sud e andare sul retro delle ⟦Ruins of Lordaeron=Rovine di Lordaeron⟧. Poi prendi l'ascensore, scendi fino a ⟦Undercity=Sepulcra⟧ vera e propria e chiedi altre indicazioni a un ⟦Undercity Guardian=Guardiano di Sepulcra⟧.", "." },
  ["d2f6a85f4588ef6f"] = { "Byancie ha spesso prestato i suoi servigi alle Sentinelle che pattugliano le terre selvagge della zona. Dovresti parlarle se vuoi imparare il ⟦First Aid=Primo Soccorso⟧.", "." },
